<?php

namespace Database\Seeders;

use App\Models\Article;
use App\Models\ArticleCategory;
use App\Models\Tag;
use Illuminate\Database\Seeder;

class GeneticsGuideSeeder extends Seeder
{
    public function run(): void
    {
        $categories = collect([
            ['name' => 'الألوان والوراثة', 'slug' => 'colors-genetics', 'description' => 'مدخل مبسط إلى الألوان والصفات الوراثية ونتائج التزاوج.', 'image' => '/images/birds/yellow-canary.jpg', 'sort_order' => 7],
            ['name' => 'الأمراض والصحة', 'slug' => 'health', 'description' => 'علامات تستحق الانتباه ومتى يلزم التواصل مع طبيب بيطري.', 'image' => '/images/birds/classic-canary.jpg', 'sort_order' => 2],
            ['name' => 'التفريخ', 'slug' => 'breeding', 'description' => 'العش والبيض والفقس والعناية بالفراخ حتى الفطام.', 'image' => '/images/birds/classic-canary.jpg', 'sort_order' => 5],
        ])->mapWithKeys(fn (array $data) => [
            $data['slug'] => ArticleCategory::firstOrCreate(['slug' => $data['slug']], $data),
        ]);

        $articles = $this->articles();

        foreach ($articles as $index => $data) {
            $article = Article::firstOrCreate(
                ['slug' => $data['slug']],
                [
                    'category_id' => $categories[$data['category']]->id,
                    'title' => $data['title'],
                    'summary' => $data['summary'],
                    'content' => $data['content'],
                    'featured_image' => $data['image'],
                    'status' => 'published',
                    'published_at' => now()->subHours(count($articles) - $index),
                ]
            );

            $tagIds = collect($data['tags'])->map(fn (string $name) => Tag::firstOrCreate(
                ['name' => $name],
                ['slug' => 'tag-'.substr(sha1($name), 0, 10)]
            )->id);
            $article->tags()->syncWithoutDetaching($tagIds);
        }
    }

